import math
from collections import defaultdict

def prime_factors(n):
    factors = defaultdict(int)
    # Check for number of 2s that divide n
    while n % 2 == 0:
        factors[2] += 1
        n //= 2
    # n must be odd at this point, so a skip of 2 (i = i + 2) can be used
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        # While i divides n, add i and divide n
        while n % i == 0:
            factors[i] += 1
            n //= i
    # If n is a prime number greater than 2
    if n > 2:
        factors[n] += 1
    return factors

def min_vertices(n, numbers):
    factor_sets = [set(prime_factors(num).keys()) for num in numbers]
    all_factors = set().union(*factor_sets)

    # Create a graph where each factor is a node
    graph = {factor: [] for factor in all_factors}

    # Add edges between factors based on divisibility
    for factor in all_factors:
        for num in numbers:
            if factor not in prime_factors(num):
                continue
            for other_factor in all_factors:
                if factor != other_factor and other_factor in prime_factors(num):
                    graph[factor].append(other_factor)

    # Count the minimum number of vertices
    visited = set()
    def dfs(node):
        if node in visited:
            return 0
        visited.add(node)
        count = 1
        for neighbor in graph[node]:
            count += dfs(neighbor)
        return count

    min_vertices_count = 0
    for factor in all_factors:
        if factor not in visited:
            min_vertices_count += dfs(factor)

    return min_vertices_count

# Read input
n = int(input().strip())
numbers = list(map(int, input().strip().split()))

